      "achados": [
        {
          "proposicao": "Na escolha do processo de desaeração para água de injeção, o stripping a gás é apresentado como preferível quando há gás sem componentes ácidos, possibilidade de queima segura e problema de espaço; a desaeração a vácuo é apresentada como preferível quando não há gás disponível e não há problema de espaço.",
          "trechos": [
            "Ee02d45e14efadca2:0:692",
            "Ee02d45e14efadca2:692:1379"
          ],
          "condicoes": [
            "tratamento de água de injeção",
            "comparação entre alternativas de processo",
            "disponibilidade ou indisponibilidade de gás",
            "restrição ou não de espaço"
          ],
          "limites": [
            "o próprio texto usa formulação de preferência geral, não regra universal",
            "a aplicabilidade depende das condições da instalação e da qualidade do gás"
          ]
        },
        {
          "proposicao": "Quando há disponibilidade de gás doce, o uso de desaeração a vácuo em dois estágios com auxílio de stripping no segundo estágio é descrito como atrativo.",
          "trechos": [
            "Ee02d45e14efadca2:692:1379"
          ],
          "condicoes": [
            "disponibilidade de gás doce",
